  const email='egometra.support@gmail.com';
  const names={de:'Deutsch',en:'English',es:'Español',fr:'Français',it:'Italiano',lt:'Lietuvių',pl:'Polski',pt:'Português',ru:'Русский',uk:'Українська'};
  function resolveLanguage(requested,device){const code=(requested||device||'en').toLowerCase().split(/[-_]/)[0];return Object.prototype.hasOwnProperty.call(content,code)?code:'en'}
  function render(language,container,showTitle=true){
    if(!container)return;
    const policy=content[resolveLanguage(language)];
    container.replaceChildren();
    const append=(tag,text)=>{const node=document.createElement(tag);node.textContent=text;container.append(node);return node};
    if(showTitle)append('h2',policy.title);
    append('p',policy.updated).className='privacy-updated';
    const operator=append('p',policy.operator+' '),contact=document.createElement('a');
    contact.textContent=email;contact.href='mailto:'+email;contact.setAttribute('translate','no');operator.append(contact);
    policy.sections.forEach(section=>{append('h3',section.title);append('p',section.text)});
    const link=append('p',''),google=document.createElement('a');google.textContent=policy.mailPolicy;google.href='https://policies.google.com/privacy';google.target='_blank';google.rel='noopener noreferrer';link.append(google);
    if(showTitle){append('p',policy.hosting.text);const hostLink=append('p',''),host=document.createElement('a');host.textContent=policy.hosting.label;host.href='https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement';host.target='_blank';host.rel='noopener noreferrer';hostLink.append(host)}
  }
  window.EgoMetraPrivacy={content,email,names,resolveLanguage,render};
